 const world=createGrappleLauncher(T),fps=createGrappleLauncher(T),hook=createGrappleHook(T),fpsRoot=new T.Group();fpsRoot.name='Grappin / bras gauche FPS';camera?.add(fpsRoot);scene.add(world.root,hook.root);
