 const glove=createGlove(handMats,{mirror:true,sleeve:true,arm:true});glove.userData.setBasePosition([-.30,-.26,-.57]);glove.userData.setForearm?.([-.15,-.3,.36]);glove.userData.animate?.({grip:.75},.016,-1);fpsRoot.add(glove,fps.root);fps.root.position.set(-.27,-.20,-.53);fps.root.rotation.y=Math.PI;
 const cableGeometry=new T.CylinderGeometry(1,1,1,6),cableMat=new T.MeshStandardMaterial({color:0x455867,metalness:.82,roughness:.38}),signalMat=new T.MeshBasicMaterial({color:0xff80b2,toneMapped:false});
 const cable=new T.InstancedMesh(cableGeometry,cableMat,12),filament=new T.InstancedMesh(cableGeometry,signalMat,12);for(const m of [cable,filament]){m.name='Grappin / câble 3D';m.count=0;m.frustumCulled=false;m.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(m);}
 const control=createGrappleControl({getGame,canControl}),point=new T.Vector3(),target=new T.Vector3(),forward=new T.Vector3(),origin=new T.Vector3(),a=new T.Vector3(),b=new T.Vector3(),delta=new T.Vector3(),mid=new T.Vector3(),scale=new T.Vector3(),up=new T.Vector3(0,1,0),q=new T.Quaternion(),matrix=new T.Matrix4();
