 const aim={direction:{x:0,y:0,z:-1}},hidden=new Map(),busyGuns=new Map();let colour=-1,lastGame=null,lastActive=false,retractUntil=-100,poseBackup=null,poseModel=null,disposed=false;
 const restoreWeapons=()=>{for(const [node,visible]of hidden)node.visible=visible;hidden.clear();for(const [gun,busy]of busyGuns){gun.userData.leftArmBusy=busy;if(gun.userData.support)gun.userData.support.visible=!!gun.userData.showSupport&&!!gun.userData.supportPoint&&!busy;}busyGuns.clear();};
 function hideOffHand(model){for(const gun of new Set([getWeapon(),model?.gun])){if(!gun)continue;if(!busyGuns.has(gun))busyGuns.set(gun,!!gun.userData.leftArmBusy);gun.userData.leftArmBusy=true;const nodes=[gun.userData.support,gun.userData.weaponModels?.[7]?.getObjectByName('DUO left')];for(const n of nodes)if(n){if(!hidden.has(n))hidden.set(n,n.visible);n.visible=false;}}
  if(renderer?.xr?.isPresenting)for(const node of getLeftController()?.children||[]){if(node.userData.weaponModels||node.userData.rlh){if(!hidden.has(node))hidden.set(node,node.visible);node.visible=!!node.userData.rlh;}}
 }
 function restorePose(){const arm=poseModel?.arms?.[0];if(arm&&poseBackup){arm.upper.quaternion.copy(poseBackup[0]);arm.fore.quaternion.copy(poseBackup[1]);}poseBackup=null;poseModel=null;}
 function orient(bone,child,to){bone.updateWorldMatrix(true,true);const s=bone.getWorldPosition(new T.Vector3()),from=child.getWorldPosition(new T.Vector3()).sub(s),d=to.clone().sub(s);if(from.lengthSq()<1e-9||d.lengthSq()<1e-9)return;const w=bone.getWorldQuaternion(new T.Quaternion()),parent=bone.parent.getWorldQuaternion(new T.Quaternion()).invert();bone.quaternion.copy(parent.multiply(new T.Quaternion().setFromUnitVectors(from.normalize(),d.normalize()).multiply(w)));bone.updateWorldMatrix(false,true);}
