  arm.upper.updateWorldMatrix(true,true);const shoulder=arm.upper.getWorldPosition(new T.Vector3()),elbow=arm.fore.getWorldPosition(new T.Vector3()),wrist=arm.hand.getWorldPosition(new T.Vector3()),u=shoulder.distanceTo(elbow),v=elbow.distanceTo(wrist),direction=new T.Vector3(game.grapple.anchor.x,game.grapple.anchor.y,game.grapple.anchor.z).sub(shoulder).normalize(),reach=u+v-.015,along=(u*u-v*v+reach*reach)/(2*reach),pole=new T.Vector3(-Math.cos(game.player.yaw||0),-.35,Math.sin(game.player.yaw||0)).addScaledVector(direction,-direction.dot(new T.Vector3(-Math.cos(game.player.yaw||0),-.35,Math.sin(game.player.yaw||0)))).normalize(),joint=shoulder.clone().addScaledVector(direction,along).addScaledVector(pole,Math.sqrt(Math.max(0,u*u-along*along)));
